package exercise
import("context";"errors";"io";"sync";"sync/atomic")
type Factory func(context.Context)(io.Closer,error)
type Service struct{resources []io.Closer;ready atomic.Bool;once sync.Once;err error}
func(s *Service)Ready()bool{return s!=nil&&s.ready.Load()}
func(s *Service)Close()error{if s==nil{return nil};s.once.Do(func(){s.ready.Store(false);for i:=len(s.resources)-1;i>=0;i--{s.err=errors.Join(s.err,s.resources[i].Close())}});return s.err}
func Start(ctx context.Context,factories []Factory)(*Service,error){
 if ctx==nil||len(factories)==0{return nil,errors.New("dependencies required")};for _,f:=range factories{if f==nil{return nil,errors.New("nil factory")}}
 s:=&Service{}
 for _,f:=range factories{
  if err:=ctx.Err();err!=nil{return nil,errors.Join(err,s.Close())}
  resource,err:=f(ctx)
  if resource!=nil{s.resources=append(s.resources,resource)}
  if err==nil&&resource==nil{err=errors.New("nil acquired resource")}
  if err==nil{err=ctx.Err()}
  if err!=nil{return nil,errors.Join(err,s.Close())}
 }
 s.ready.Store(true);return s,nil
}
```

原题知识说明：
交付显式启动依赖图和每个资源的获取、可用、关闭状态，避免把会失败的网络初始化藏在无法返回error的包init中。构造阶段按依赖顺序获取资源，任一阶段失败就逆序释放已经获得的资源，且清理失败要附带报告而非覆盖最初错误。对已启动的订阅和后台任务，必须先停止接受工作并等待退出，再关闭其依赖；Ready只在所有必需阶段完成后发布。验收在每个边界注入连接失败、取消和端口占用，证明不会留下订阅、句柄或半就绪实例，也不会重复执行外部初始化动作。回退运行已验证制品时先完成失败实例清理，若某外部动作不可逆则进入人工接管状态，不能只调用recover继续对外服务。

