type closer func()error
func(c closer)Close()error{return c()}
func TestBoundariesAndOriginalError(t *testing.T){
 for boundary:=0;boundary<3;boundary++{
  primary:=errors.New("acquire-original");cleanup:=errors.New("cleanup-extra");events:=[]int{};calls:=0;fs:=[]Factory{}
  for i:=0;i<3;i++{n:=i;fs=append(fs,func(context.Context)(io.Closer,error){calls++;r:=closer(func()error{events=append(events,n);return cleanup});if n==boundary{return r,primary};return r,nil})}
  s,err:=Start(context.Background(),fs);want:=[]int{};for i:=boundary;i>=0;i--{want=append(want,i)}
  if s!=nil||!errors.Is(err,primary)||!errors.Is(err,cleanup)||calls!=boundary+1||!reflect.DeepEqual(events,want){t.Fatal("partial acquisition, original error or reverse release lost",boundary,s,err,calls,events)}
 }
}
func TestValidationCancellationAndNil(t *testing.T){
 calls:=0;f:=Factory(func(context.Context)(io.Closer,error){calls++;return closer(func()error{return nil}),nil})
 for _,item:=range []struct{ctx context.Context;fs []Factory}{{nil,[]Factory{f}},{context.Background(),nil},{context.Background(),[]Factory{f,nil}}}{s,err:=Start(item.ctx,item.fs);if s!=nil||err==nil||calls!=0{t.Fatal("invalid dependencies acquired resources")}}
 ctx,cancel:=context.WithCancel(context.Background());cancel();s,err:=Start(ctx,[]Factory{f});if s!=nil||!errors.Is(err,context.Canceled)||calls!=0{t.Fatal("pre-cancel acquired resource")}
 ctx,cancel=context.WithCancel(context.Background());closed:=0
 fs:=[]Factory{func(context.Context)(io.Closer,error){cancel();return closer(func()error{closed++;return nil}),nil},f};s,err=Start(ctx,fs)
 if s!=nil||!errors.Is(err,context.Canceled)||closed!=1||calls!=0{t.Fatal("cancellation between acquire and ready leaked resource",s,err,closed,calls)}
 s,err=Start(context.Background(),[]Factory{func(context.Context)(io.Closer,error){return nil,nil}});if s!=nil||err==nil{t.Fatal("nil successful acquisition accepted")}
}
