 blocker,err:=net.Listen("tcp","127.0.0.1:0");if err!=nil{t.Fatal(err)};defer blocker.Close();occupied:=blocker.Addr().String();dbAddress:="";events:=[]string{};var subscriptionDone <-chan struct{};var original error
